weights = {"impact": 0.4, "data": 0.3, "sponsor": 0.2, "scope": 0.1}

# scores from 1 (poor) to 5 (strong); example values only
candidates = {
    "Label rework on line 2":        {"impact": 3, "data": 5, "sponsor": 4, "scope": 5},
    "Batch record review delays":    {"impact": 5, "data": 3, "sponsor": 5, "scope": 3},
    "All supplier quality problems": {"impact": 5, "data": 2, "sponsor": 3, "scope": 1},
}

for name, s in candidates.items():
    total = sum(weights[k] * s[k] for k in weights)
    print(f"{total:.1f}  {name}")
# 4.0  Label rework on line 2
# 4.2  Batch record review delays
# 3.3  All supplier quality problems
